export const tripDays: TripDay[] = rawTripDays.map((day) => {
  const update = timingUpdates[day.id];
  // Open Tokyo days are intentionally blank: don't even enrich their retired
  // legacy schedules with transfers, meal fallbacks, or restaurant backups.
  const updatedPlaces = (openTokyoDayIds.has(day.id) ? [] : day.places)
    .filter((item) => item.type !== 'stay' && !(day.id === '2026-11-02' && item.id === 'kanmangafuchi') && !update?.remove?.includes(item.id));
  const dayPlaces = (openTokyoDayIds.has(day.id) ? [] : [...updatedPlaces, ...(update?.add ?? []), ...(update?.addBackups ?? []), ...(namedFoodBackupsByDate[day.id] ?? []), ...(additionalPlacesByDate[day.id] ?? [])])
    .filter((item) => !update?.remove?.includes(item.id))
    .map((item) => ({ ...item, ...update?.replace?.[item.id] }) as Place)
    .concat(stayPlacesForDate(day.date));
  const plannedMeals = new Set(dayPlaces
    .filter((item) => item.mealContext && item.role !== 'backup')
    .map((item) => item.mealContext));
  const baseCoordinates = day.base.startsWith('Sapporo') ? c.sapporo
    : day.base.startsWith('Hakodate') ? c.hakodate
      : day.base.startsWith('Sendai') ? c.sendai
        : day.base.startsWith('Nikko') ? c.nikko : c.tokyo;
  const intentionalMealFallbacks = (openTokyoDayIds.has(day.id) ? [] : (['breakfast', 'lunch', 'dinner'] as const)
    .filter((meal) => !plannedMeals.has(meal))
    .map((meal) => place(
      `${day.date}-${meal}-flexible-meal`,
      `Flexible ${meal} · choose locally`,
      'food',
      `Intentional flexible meal: no restaurant is selected for this ${meal}; choose a convenient open option near the day's route or hotel. This is a Google Maps search area, not a named venue or an opening-hours claim. Cuisine, dish and price are not verified; check the menu and current service before choosing.`,
      `${meal} restaurants near ${day.base}, Japan`,
      [baseCoordinates[0] + 0.0002, baseCoordinates[1] + 0.0002],
      { mealContext: meal, cuisine: 'Flexible local dining', signature: 'No signature dish selected', role: 'primary', fallback: true, verification: 'research' },
    )));
  const foodDetailsReviewed = [...dayPlaces, ...intentionalMealFallbacks].map((item) => {
    if (item.type !== 'food' || !item.mealContext) return item;
    const flexiblePrimary = flexibleFoodPrimaryIds.has(item.id);
    const notes = [
      !item.signature ? 'Signature dish not verified; check the current menu.' : '',
      !item.priceBand ? 'Price band not verified; check current menu prices.' : 'Price band is indicative only; confirm current menu prices.',
    ].filter(Boolean);
    const flexibleNote = flexiblePrimary ? ' Intentional flexible meal: this is an area/search plan, not a selected restaurant or opening-hours claim.' : '';
    return {
      ...item,
      ...(flexiblePrimary ? { fallback: true } : {}),
      cuisine: item.cuisine ?? 'Cuisine not verified',
      signature: item.signature ?? 'Signature dish not verified',
      verification: item.verification === 'confirmed' ? 'verify-before-trip' : item.verification,
      description: `${item.description} ${notes.join(' ')}${flexibleNote}`.trim(),
    };
  });
  const mealAnchors = foodDetailsReviewed.filter((item) =>
    item.role !== 'backup' && (item.type === 'food' || (item.type === 'sight' && item.mealContext)),
  );
  const nearbyFoodBackups = mealAnchors.flatMap((primary) => {
    if (foodDetailsReviewed.some((item) => item.role === 'backup' && item.type === 'food' && item.mealContext === primary.mealContext)) return [];
    const [latitude, longitude] = primary.coordinates ?? c.tokyo;
    const meal = primary.mealContext;
    const cuisine = primary.cuisine ?? `${day.base} local food`;
    return [place(
      `${primary.id}-nearby-food-backup`,
      `Nearby ${meal ?? 'food'} search · generic fallback`,
      'food',
      `Generic Google Maps search area near “${primary.name}”, not a named or individually verified restaurant. Use it if the primary choice does not work; check current opening hours, queue and route before setting out. Map pin is an approximate search anchor, not a venue address. Signature dish not verified. Price band is not verified for this search area.`,
      `${cuisine} restaurants near ${primary.mapsQuery}`,
      [latitude + 0.00035, longitude + 0.00035],
      { mealContext: meal, cuisine, signature: 'No signature dish selected', priceBand: primary.priceBand, role: 'backup', fallback: true, verification: 'research' },
    )];
  });
  return {
    ...day,
    ...update?.day,
    ...(day.id === '2026-10-31' ? { title: 'Sendai → Tokyo · travel day', summary: 'Take the reserved-seat Hayabusa to Tokyo and check in at the booked Ikebukuro hotel. No sightseeing or evening plans are scheduled.', keyDay: false, pacing: 'light' as const, tags: ['transit'] } : {}),
    ...openTokyoDayUpdates[day.id],
    ...(openTokyoDayIds.has(day.id) || day.id === '2026-10-31' || day.id === '2026-11-11' ? { dailyEstimateJPY: undefined } : {}),
    places: [...foodDetailsReviewed, ...nearbyFoodBackups]
      .filter((item) => openTokyoDayIds.has(day.id) ? item.type === 'stay' : day.id === '2026-10-31' ? item.type === 'stay' || ['hayabusa-sendai-tokyo', 'tokyo-station-arrival'].includes(item.id) : day.id === '2026-11-11' ? item.type === 'stay' || item.type === 'transit' : true)
      .sort((a, b) => (a.startTime ?? '99:99').localeCompare(b.startTime ?? '99:99')),
  };
});

